package com.knowflow.learning.adaptive;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.knowflow.exception.BusinessException;import com.knowflow.learning.privatequiz.PrivateQuizService;import com.knowflow.learning.evidence.LearningEvidenceSources;import com.knowflow.learning.actions.LearningWriteGuard;import jakarta.annotation.PostConstruct;import lombok.RequiredArgsConstructor;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
/** Session lineage only. Questions, answer snapshots, grading and receipts stay in PrivateQuiz. */
@Service @RequiredArgsConstructor @ConditionalOnProperty(name={"knowflow.product.adaptive-learning.enabled","knowflow.product.private-quiz.enabled"},havingValue="true")
public class InterleavedPracticeService {
 private final JdbcTemplate sql;private final ObjectMapper json;private final PrivateQuizService quizzes;private final LearningEvidenceSources scope;private final LearningWriteGuard guard;
 public record Topic(Long knowledgeId,Long quizId){} public record Start(String requestId,List<Topic> topics,Integer count){}public record Answers(List<String> answers){}
 @PostConstruct void init(){sql.execute("CREATE TABLE IF NOT EXISTS interleaved_session(id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT NOT NULL,request_id VARCHAR(80) NOT NULL,input_json LONGTEXT NOT NULL,refs_json LONGTEXT NOT NULL,state VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,completed_at TIMESTAMP(6),UNIQUE(owner_id,request_id))");}
 private String write(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new BusinessException(500,"交错练习序列化失败");}}
 private <T>T read(Object v,TypeReference<T> t){try{return json.readValue(v.toString(),t);}catch(Exception e){throw new BusinessException(500,"交错练习记录损坏");}}
 private long id(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 private Map<String,Object> own(long u,long id,boolean lock){var rows=sql.queryForList("SELECT * FROM interleaved_session WHERE id=? AND owner_id=?"+(lock?" FOR UPDATE":""),id,u);if(rows.isEmpty())throw new BusinessException(404,"交错练习不存在");return rows.get(0);}
 public Map<String,Object> pool(long u){return Map.of("quizzes",quizzes.list(u,null).stream().filter(q->"SAVED".equals(q.get("state"))).toList(),"association","USER_CONFIRMED_IDENTITY_NOT_MASTERY","countOptions",List.of(4,6));}
 private void validate(long u,Start r){if(r==null||r.requestId()==null||!r.requestId().matches("[A-Za-z0-9_-]{8,64}")||r.topics()==null||r.topics().size()!=2||r.count()==null||!Set.of(4,6).contains(r.count()))throw new BusinessException(400,"请选择两个专题和4或6道题");var kids=new HashSet<Long>();var qids=new HashSet<Long>();for(var t:r.topics()){if(t==null||t.knowledgeId()==null||t.quizId()==null||t.knowledgeId()<1||t.quizId()<1||!kids.add(t.knowledgeId())||!qids.add(t.quizId()))throw new BusinessException(400,"需要两个不同知识点及两个不同原题版");scope.requireKnowledge(t.knowledgeId(),u);var q=quizzes.detail(u,t.quizId());if(!"SAVED".equals(q.get("state"))||((List<?>)q.get("questions")).size()<r.count()/2)throw new BusinessException(409,"已保存且可用的原题不足，不补造题目");}}
 @Transactional public Map<String,Object> start(long u,Start r){validate(u,r);guard.lock(u);String input=write(r);var old=sql.queryForList("SELECT * FROM interleaved_session WHERE owner_id=? AND request_id=?",u,r.requestId());if(!old.isEmpty()){if(!old.get(0).get("input_json").equals(input))throw new BusinessException(409,"同一请求已用于其他题目");return view(u,old.get(0));}var refs=new ArrayList<Map<String,Object>>();for(int i=0;i<r.count();i++){var t=r.topics().get(i%2);var a=quizzes.beginMicro(u,t.quizId(),i/2,"i04_"+r.requestId()+"_"+i);refs.add(Map.of("knowledgeId",t.knowledgeId(),"quizId",t.quizId(),"questionIndex",i/2,"quizVersion",a.get("version"),"attemptId",a.get("id"),"association","USER_CONFIRMED","conditions","CLOSED_BOOK_PREVIEW_EXPOSED"));}sql.update("INSERT INTO interleaved_session(owner_id,request_id,input_json,refs_json,state,created_at) VALUES(?,?,?,?,'IN_PROGRESS',CURRENT_TIMESTAMP)",u,r.requestId(),input,write(refs));return view(u,sql.queryForList("SELECT * FROM interleaved_session WHERE owner_id=? AND request_id=?",u,r.requestId()).get(0));}
 public Map<String,Object> get(long u,long id){return view(u,own(u,id,false));}
 private Map<String,Object> view(long u,Map<String,Object> row){List<Map<String,Object>> refs=read(row.get("refs_json"),new TypeReference<>(){});var items=new ArrayList<Map<String,Object>>();for(var ref:refs){scope.requireKnowledge(id(ref,"knowledgeId"),u);var a=quizzes.getAttempt(u,id(ref,"attemptId"));var item=new LinkedHashMap<>(ref);item.put("attempt",a);items.add(item);}var out=new LinkedHashMap<String,Object>();out.put("id",row.get("id"));out.put("state",row.get("state"));out.put("createdAt",row.get("created_at"));out.put("completedAt",row.get("completed_at"));out.put("items",items);out.put("gradingSource","ORIGINAL_PRIVATE_QUIZ_EXAM_GRADER");out.put("masteryEffect","NONE_SESSION_ONLY");return out;}
 @Transactional public Map<String,Object> submit(long u,long id,Answers r){guard.lock(u);var row=own(u,id,true);view(u,row);List<Map<String,Object>> refs=read(row.get("refs_json"),new TypeReference<>(){});if(r==null||r.answers()==null||r.answers().size()!=refs.size()||r.answers().stream().anyMatch(a->a==null||a.length()>2000))throw new BusinessException(400,"请提交完整答卷");for(int i=0;i<refs.size();i++)quizzes.submitMicro(u,id(refs.get(i),"attemptId"),r.answers().get(i));if(!"COMPLETED".equals(row.get("state")))sql.update("UPDATE interleaved_session SET state='COMPLETED',completed_at=CURRENT_TIMESTAMP WHERE id=? AND owner_id=?",id,u);return get(u,id);}
 public List<Map<String,Object>> history(long u){var out=new ArrayList<Map<String,Object>>();for(var row:sql.queryForList("SELECT * FROM interleaved_session WHERE owner_id=? ORDER BY id DESC LIMIT 100",u)){try{out.add(view(u,row));}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;out.add(Map.of("id",row.get("id"),"state","SOURCE_UNAVAILABLE","items",List.of()));}}return out;}
}
